        audiobook: true,
        amazon_url: 'https://www.amazon.com/s?k=The+Way+of+Kings+Brandon+Sanderson&tag=librariancura-20',
        bookshop_url: 'https://bookshop.org/search?keywords=The+Way+of+Kings+Brandon+Sanderson&affiliate=122720',
